INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('3f5fcd82-0038-4cac-b6fc-9bea8821d7ea', '707de2c6-0329-4636-8d99-816586419ee4', 'A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-1030). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d3df1311-f15f-4359-aeee-12b3e471b577', '707de2c6-0329-4636-8d99-816586419ee4', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2dc2e13d-a7ad-40d5-88bd-d2ea843adf0f', '707de2c6-0329-4636-8d99-816586419ee4', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2e81dff9-a18a-4434-a481-0068a97ae31c', '707de2c6-0329-4636-8d99-816586419ee4', 'C', 'Dispense the full supply and annotate the words and figures manually without prescriber amendment', 0, 'Illegal for total quantity. Pharmacists may only amend minor spelling/typographical errors or words/figures if omitted in specific limited home office circular exemptions.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('24a23192-1e99-4bdd-b8a2-908dcf0c0a51', '707de2c6-0329-4636-8d99-816586419ee4', 'D', 'Accept validity for 6 months as per standard prescription rules', 0, 'Standard POMs are valid for 6 months, but Controlled Drugs (Schedule 2-4) expire at 28 days.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7c63722b-8468-4b38-ac8c-2e729461b86c', '707de2c6-0329-4636-8d99-816586419ee4', 'E', 'Dispense under emergency supply regulations', 0, 'Schedule 2 and 3 CDs cannot be supplied under emergency supply regulations at patient request (except phenobarbital for epilepsy).', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('100f78dd-494b-437e-8376-c89f4bacff9f', '707de2c6-0329-4636-8d99-816586419ee4', 'Schedule 2 and 3 CD prescriptions are valid for 28 days and must contain quantity in both words and figures.', 'Installment prescriptions (FP10MDA) must have the first installment dispensed within 28 days of signing. Reference: Misuse of Drugs Regulations 2001 & MEP 46.', 'Misuse of Drugs Regulations 2001 & MEP 46', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('227bc267-6c85-443a-af0f-2084b969e965', '707de2c6-0329-4636-8d99-816586419ee4', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'ACP-Q-1031', 1, 'published', 'p-mpharm', 'sub-uti-first', 'hard', 'sba', 'gp', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('72ca5c83-f824-4a29-a955-0affeddd3e9e', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'A 24-year-old male attends community pharmacy with a severe sore throat of 2 days duration. Examination shows purulent tonsillar exudate, severe tonsillar inflammation, temperature 38.6°C, and no cough. FeverPAIN score is calculated as 4. (Case Ref: PHARMACY-FIRST-1031). Relevant physiological and medication history have been reviewed.', 'What is the appropriate action under the Pharmacy First clinical protocol?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0e9061c7-bdb0-4927-b098-a3acc9a4aa0a', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8176e0db-9ee4-4fd9-8e7d-5de8ac7215b4', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dcd825f0-2732-4024-97cb-9d4d83de4a09', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c137dc0d-f51a-48f5-9006-6ce398ebb6fa', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'D', 'Supply Co-amoxiclav 625 mg TDS', 0, 'Inappropriate broad-spectrum antibiotic. Amoxicillin/co-amoxiclav may cause severe morbilliform rash in undiagnosed glandular fever (EBV).', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f8137f01-fbfb-489f-aac3-b201a1aed962', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'E', 'Supply Penicillin V for 14 days', 0, 'NICE NG84 guidelines mandate a 5-day course for acute group A streptococcal pharyngitis.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('d2ce32d2-5d38-42ce-af21-4287bcaa34a3', '0693743f-4be3-4f95-ae37-ff9a89e3c82b', 'FeverPAIN score 4-5 warrants targeted antimicrobial treatment (Penicillin V for 5 days). Avoid amoxicillin if glandular fever is suspected.', 'FeverPAIN components: Fever, Purulent tonsils, Attend in <= 3 days, Inflamed tonsils, No cough/coryza. Reference: NHS England Pharmacy First Clinical Pathway & NICE NG84.', 'NHS England Pharmacy First Clinical Pathway & NICE NG84', 1789734485, 1789734485);
