INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('51da018a-55f9-476b-acad-73a283538d4e', '335513eb-efff-43db-86e3-c0601970ee44', 'A 24-year-old male attends community pharmacy with a severe sore throat of 2 days duration. Examination shows purulent tonsillar exudate, severe tonsillar inflammation, temperature 38.6°C, and no cough. FeverPAIN score is calculated as 4. (Case Ref: PHARMACY-FIRST-1135). Relevant physiological and medication history have been reviewed.', 'What is the appropriate action under the Pharmacy First clinical protocol?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3ef8ed08-1b5f-4e32-ae00-b54b8dfa59b3', '335513eb-efff-43db-86e3-c0601970ee44', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b8027dd9-a872-4926-a507-830e1992258f', '335513eb-efff-43db-86e3-c0601970ee44', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('09bdba46-f13d-4e2c-992c-5ad56229fc99', '335513eb-efff-43db-86e3-c0601970ee44', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789734485);
