INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('4bfb765c-b918-46fa-ba7d-4afe9e76f575', 'c6c884a5-b878-4a3a-9a4e-2d3f1dfd3c3f', 'A 45-year-old patient with confirmed H. pylori on stool antigen test has no known drug allergies and has not taken macrolide antibiotics previously. (Case Ref: GASTROINTESTINAL-1136). Relevant physiological and medication history have been reviewed.', 'Which 7-day eradication regimen is recommended first-line by NICE?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9cb4f0fa-8b92-4260-ad76-aa0a466cd9d1', 'c6c884a5-b878-4a3a-9a4e-2d3f1dfd3c3f', 'A', 'PPI twice daily + Amoxicillin 1 g twice daily + Clarithromycin 500 mg twice daily for 7 days', 1, 'Correct. Standard UK first-line triple eradication consists of a full-dose PPI bd + amoxicillin 1g bd + clarithromycin 500mg bd (or metronidazole 400mg bd) for 7 days.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c295bc93-469a-45a9-ac99-30d79c8715d3', 'c6c884a5-b878-4a3a-9a4e-2d3f1dfd3c3f', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('da1a3dd7-fd89-4b38-922c-cc1637bba6e0', 'c6c884a5-b878-4a3a-9a4e-2d3f1dfd3c3f', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f810b2e4-024a-4e74-8708-29a4cdeb7ec3', 'c6c884a5-b878-4a3a-9a4e-2d3f1dfd3c3f', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789734485);
